-- sentosa-janda-baik  (updated_at was 2025-11-10T16:21:56.000Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/low.webp","sizeBytes":55930},"high":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/high.webp","sizeBytes":229478},"original":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover.jpg","sizeBytes":349313}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/crop-16x9-og.webp?v=0.4362_0.8614-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/crop-4x3-article-card.webp?v=0.4362_0.8614-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/crop-4x5-mobile-cover.webp?v=0.4362_0.8614-g48c0b959","width":976,"height":1220},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396879848-cover/crop-4.3x1-desktop-hero.webp?v=0.4362_0.8614-g48c0b959","width":1706,"height":485}}'::jsonb,
  cover_image_focal_point = '{"x":0.4362250879249708,"y":0.8613901639344261,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Berlatarbelakangkan suasana tropika yang subur di Sentosa, Janda Baik, majlis perkahwinan ini menonjol sebagai contoh gabungan cerita budaya dan rekaan yang bermakna. Majlis ini meraikan penyatuan dua keluarga pengantin perempuan berketurunan Jawa, manakala pengantin lelaki berasal daripada warisan Melayu-Baba. Keseluruhan acara diolah dengan indah sebagai penghormatan moden kepada kemegahan istana zaman dahulu, menampilkan suasana yang peribadi, elegan, dan penuh nilai seni.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396886003-RW-AzizulSheheraDinieSentosaJandaBaik-2-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396890441-RW-AzizulSheheraDinieSentosaJandaBaik-3-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396893927-RW-AzizulSheheraDinieSentosaJandaBaik-4-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Dalam suasana yang memancarkan keanggunan klasik, pasangan ini memilih untuk menzahirkan kisah cinta mereka melalui elemen yang berakar pada nilai warisan. Pengantin perempuan tampil menawan dengan kebaya rekaan khas oleh Toton, dihasilkan daripada kain renda terpakai yang diberi nafas baharu gabungan antara kelestarian dan kehalusan seni pertukangan. Penampilannya dilengkapi dengan mahkota bunga tropika dan jambangan unik daripada jantung pisang serta petai, pilihan yang luar biasa namun penuh makna, melambangkan keindahan semula jadi dan simbol kesuburan. Pengantin lelaki pula mengenakan sut Kraton beskap yang digayakan bersama baju Melayu rekaan khas Omar Ali, disulam halus dengan ikrar cintanya sendiri satu sentuhan puitis yang sederhana tetapi sangat bermakna.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396897108-RW-AzizulSheheraDinieSentosaJandaBaik-5-scaled/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396899041-RW-AzizulSheheraDinieSentosaJandaBaik-6-scaled-e17/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396901040-RW-AzizulSheheraDinieSentosaJandaBaik-7-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396905925-RW-AzizulSheheraDinieSentosaJandaBaik-8-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396914160-RW-AzizulSheheraDinieSentosaJandaBaik-9-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Rekaan keseluruhan majlis perkahwinan ini jelas diinspirasikan oleh kehidupan kampung dan warisan diraja. Alam semula jadi menjadi latar serta hiasan utama kolam yang dipenuhi bunga teratai, flora tropika yang subur, dan laluan kayu tradisional mencipta suasana romantik yang mengimbau keindahan zaman dahulu.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396923179-RW-AzizulSheheraDinieSentosaJandaBaik-10-scaled/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396925055-RW-AzizulSheheraDinieSentosaJandaBaik-11-scaled/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396927797-RW-AzizulSheheraDinieSentosaJandaBaik-12-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396933646-RW-AzizulSheheraDinieSentosaJandaBaik-13-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396938113-RW-AzizulSheheraDinieSentosaJandaBaik-14-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396942845-RW-AzizulSheheraDinieSentosaJandaBaik-15-1024x683/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Para tetamu dijamu dengan hidangan gaya kampung yang disajikan di bawah cahaya matahari yang lembut. Meja makan dihias dengan kain linen berwarna semula jadi, dihiasi buah-buahan tropika dan hasil segar daripada D&S Farmers Market. Buah-buahan dan sayur-sayuran ini bukan sahaja dijadikan hiasan tengah meja, tetapi juga cenderamata untuk dibawa pulang. Para tetamu dijemput mengisi beg mereka sendiri satu idea yang menarik dan mesra alam, menjadikan majlis ini lebih bermakna serta berkonsepkan kelestarian.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396945060-RW-AzizulSheheraDinieSentosaJandaBaik-16-scaled/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396947081-RW-AzizulSheheraDinieSentosaJandaBaik-17-scaled/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396950566-RW-AzizulSheheraDinieSentosaJandaBaik-18-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396960823-RW-AzizulSheheraDinieSentosaJandaBaik-19-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396967979-RW-AzizulSheheraDinieSentosaJandaBaik-20-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Sebagai ganti kepada buku tetamu tradisional, para tetamu menandatangani majalah seni bina lama yang diubah menjadi kenangan meja kopi untuk pasangan pengantin iaitu satu idea kreatif dan moden yang sarat dengan ucapan penuh makna. Antara detik paling mencuit hati dan menjadi tumpuan ialah piñata bertemakan golf, sebagai simbol minat pengantin lelaki terhadap sukan tersebut. Dipenuhi dengan gula-gula dan konfeti, piñata itu meletup dengan meriah, mencetuskan suasana ceria dan tawa kanak-kanak yang berebut mengutip isinya.","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396971927-RW-AzizulSheheraDinieSentosaJandaBaik-21-1024x683/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396976437-RW-AzizulSheheraDinieSentosaJandaBaik-22-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396984151-RW-AzizulSheheraDinieSentosaJandaBaik-23-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396989552-RW-AzizulSheheraDinieSentosaJandaBaik-24-768x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sentosa-janda-baik/1787396997177-RW-AzizulSheheraDinieSentosaJandaBaik-25-683x1024/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Para tetamu yang hadir dengan mengenakan kebaya dan pakaian linen ringan menikmati minuman long chan soda serta manisan tradisional tempatan, yang menambahkan suasana santai dan meriah pada majlis tersebut. Gabungan elemen klasik, keakraban keluarga, dan sentuhan moden menjadikan setiap momen terasa anggun, mesra, dan penuh keceriaan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kredit Vendor:","type":"text","marks":[{"type":"bold"}]},{"text":" ","type":"text"}]},{"type":"paragraph","content":[{"text":"Lokasi: Sentosa ","type":"text"},{"text":"Janda Baik","type":"text","marks":[{"type":"link","attrs":{"rel":"noreferrer noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/nature-filled-wedding-venues-in-janda-baik-youll-love/","class":null,"target":"_blank"}}]}]},{"type":"paragraph","content":[{"text":"Jurugambar: Azizul Azman & Sentralismo","type":"text"}]},{"type":"paragraph","content":[{"text":"Juruvideo: Sentralismo","type":"text"}]},{"type":"paragraph","content":[{"text":"Penyelaras Dekorasi: Munstara Events","type":"text"}]},{"type":"paragraph","content":[{"text":"Pereka Bunga: Ifzan Ibrahim","type":"text"}]},{"type":"paragraph","content":[{"text":"Busana Pengantin Perempuan: Toton, Hani Mokhtar","type":"text"}]},{"type":"paragraph","content":[{"text":"Kasut Pengantin Perempuan","type":"text","marks":[{"type":"link","attrs":{"rel":"noreferrer noopener","href":"https://theweddingnotebook.com/inspire/fashion-and-beauty/stylish-brands-for-wedding-shoes-on-a-budget/","class":null,"target":"_blank"}}]},{"text":": Marista Santividya","type":"text"}]},{"type":"paragraph","content":[{"text":"Solekan","type":"text","marks":[{"type":"link","attrs":{"rel":"noreferrer noopener","href":"https://theweddingnotebook.com/inspire/fashion-and-beauty/10-bridal-makeup-artist-to-get-you-looking-your-best/","class":null,"target":"_blank"}}]},{"text":" & Gaya Rambut: Feeka, Nazlivingastyle, Austouxh, Bellahud","type":"text"}]},{"type":"paragraph","content":[{"text":"Aksesori Rambut: Hani Mokhtar","type":"text"}]},{"type":"paragraph","content":[{"text":"Busana Pengantin Lelaki: Kraton, Omar Ali","type":"text"}]},{"type":"paragraph","content":[{"text":"Busana Bridesmaid: Bespoke Batik","type":"text"}]},{"type":"paragraph","content":[{"text":"Busana Groomsmen: Bespoke Batik","type":"text"}]},{"type":"paragraph","content":[{"text":"Katering: SOCC Caterer","type":"text"}]},{"type":"paragraph","content":[{"text":"Kek: Wakenabake","type":"text"}]},{"type":"paragraph","content":[{"text":"Set Jemputan & Alat Tulis: Eelhum & Santuari Sanubari","type":"text"}]},{"type":"paragraph","content":[{"text":"Persembahan: Syerot (Biola & Piano)","type":"text"}]},{"type":"paragraph","content":[{"text":"Cincin Pertunangan: Kaharo (Rekaan Khas)","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph"}]}'::jsonb
