update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/low.webp","sizeBytes":15184},"high":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/high.webp","sizeBytes":35660},"original":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover.jpg","sizeBytes":416719}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/crop-16x9-og.webp?v=0.1875_0.5888-g48c0b959","width":800,"height":420},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/crop-4x3-article-card.webp?v=0.1875_0.5888-g48c0b959","width":667,"height":500},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/crop-4x5-mobile-cover.webp?v=0.1875_0.5888-g48c0b959","width":400,"height":500},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396701276-cover/crop-4.3x1-desktop-hero.webp?v=0.1875_0.5888-g48c0b959","width":800,"height":227}}'::jsonb,
  cover_image_focal_point = '{"x":0.1875,"y":0.5888,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Merancang majlis perkahwinan bukanlah tugas mudah, terutamanya apabila melibatkan keputusan besar seperti ","type":"text"},{"text":"sewa dewan kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/beautiful-wedding-venues-in-malaysia/","class":null,"target":"_blank"}}]},{"text":". Ramai pasangan terburu-buru membayar deposit tanpa menyemak butiran penting lalu menyesal pada hari majlis. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Berikut ialah checklist sewa dewan kahwin sebagai panduan sebelum anda membuat keputusan dan bayaran deposit.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"1. Rancang Bajet Anda","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396705595-IN-SewaDewanKahwin-RancangBajet/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Langkah pertama dan paling penting dalam proses sewa dewan kahwin ialah menetapkan bajet yang realistik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bajet bukan sekadar tentang harga sewa dewan semata-mata, tetapi juga perlu merangkumi pelbagai kos tambahan seperti katering, dekorasi, sistem bunyi, pelamin, pakaian, serta kelengkapan majlis yang lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anda perlu bertanya kepada diri sendiri adakah anda mahukan majlis yang mewah di hotel lima bintang atau suasana yang lebih santai di dewan serbaguna? ","type":"text"}]},{"type":"paragraph","content":[{"text":"Jika ingin berjimat, anda boleh menganjurkan majlis di sebelah pihak sahaja. Dewan serbaguna atau masjid biasanya lebih berpatutan, manakala hotel pula menawarkan pakej serba lengkap dengan penginapan pengantin dan katering sekali gus.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"2. Tentukan Lokasi yang Mudah Diakses","type":"text"}]},{"type":"paragraph","content":[{"text":"Lokasi memainkan peranan besar dalam menentukan keselesaan dan kelancaran majlis perkahwinan anda. Dewan yang berdekatan dengan rumah pengantin atau tempat tinggal keluarga memudahkan urusan logistik, penghantaran barang dan pemantauan persiapan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pilih dewan yang mudah diakses oleh tetamu, mempunyai laluan jelas, dan tidak jauh dari jalan utama. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan yang terletak di kawasan strategik bukan sahaja memudahkan perjalanan, tetapi juga mengelakkan tetamu daripada tersesat atau lewat hadir.","type":"text"}]},{"type":"paragraph","content":[{"text":"Faktor seperti kemudahan awam, hotel berhampiran, serta keselamatan kawasan sekitar juga perlu diambil kira terutamanya jika anda menjemput tetamu dari luar daerah.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"3. Saiz Dewan dan Kapasiti Tetamu","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396706866-IN-SewaDewanKahwin-SaizDewan/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Kapasiti dewan perlu seimbang dengan bilangan tetamu yang dijemput. Dewan yang terlalu kecil akan menyebabkan tetamu berhimpit, manakala dewan yang terlalu besar boleh membuatkan suasana terasa kosong dan hambar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sebelum menempah, semak had maksimum meja dan kerusi yang boleh dimuatkan. Jika anda merancang konsep majlis duduk bersila atau ","type":"text"},{"text":"buffet style","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/food-caterers-to-cater-your-wedding/","class":null,"target":"_blank"}},{"type":"italic"}]},{"text":", pastikan ruang mencukupi untuk pergerakan tetamu dan aktiviti seperti sesi bergambar atau persembahan. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan yang ideal ialah dewan yang mampu memberikan ruang selesa untuk semua tanpa kelihatan terlalu padat atau terlalu luas.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"4. Fasiliti dan Kemudahan","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396708236-IN-SewaDewanKahwin-Fasiliti/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Salah satu kelebihan utama sewa dewan kahwin ialah kemudahan yang disediakan. Antara perkara yang perlu anda periksa ialah:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tandas dan Surau:","type":"text","marks":[{"type":"bold"}]},{"text":" Pastikan bersih dan berfungsi dengan baik.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penghawa Dingin / Kipas:","type":"text","marks":[{"type":"bold"}]},{"text":" Untuk keselesaan tetamu sepanjang majlis berlangsung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bilik Persalinan:","type":"text","marks":[{"type":"bold"}]},{"text":" Bagi pengantin bersiap atau menukar pakaian dengan privasi.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sistem Bunyi dan Pencahayaan:","type":"text","marks":[{"type":"bold"}]},{"text":" Pastikan bunyi jelas dan lampu cukup terang untuk rakaman gambar dan video.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Peralatan Majlis:","type":"text","marks":[{"type":"bold"}]},{"text":" Seperti mikrofon, meja VIP, podium dan pentas utama.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Jangan lupa juga semak keadaan sebenar fasiliti ini bukan sekadar percaya kepada gambar promosi. Kadang-kadang, gambar dalam iklan kelihatan sempurna tetapi realitinya berbeza.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"5. Utamakan Keselesaan Tetamu","type":"text"}]},{"type":"paragraph","content":[{"text":"Kejayaan sesebuah majlis bukan hanya bergantung kepada pengantin, tetapi juga kepada keselesaan tetamu yang hadir. Pilih dewan yang mempunyai tempat duduk empuk, laluan keluar masuk yang mudah, serta kawasan menunggu yang luas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jika ada tetamu berusia atau yang menggunakan kerusi roda, pastikan dewan mesra OKU dengan laluan rata dan tandas khas. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi majlis besar, kemudahan seperti kipas tambahan atau penyejuk udara bergerak boleh membuatkan suasana lebih menyenangkan. Ingat, tetamu yang selesa akan pulang dengan senyuman dan kenangan manis dari majlis anda.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"6. Tema Majlis dan Dekorasi","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396709495-IN-SewaDewanKahwin-TemaMajlis/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Tema majlis ialah elemen yang mencerminkan keperibadian pasangan. Sama ada anda memilih tema moden, klasik, tradisional atau garden wedding, pastikan dewan yang dipilih sesuai dengan konsep tersebut.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sesetengah dewan menawarkan pakej hiasan lengkap termasuk pelamin, bunga segar, meja makan beradab dan pencahayaan romantik. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Namun, jika anda ingin membawa vendor sendiri, pastikan pihak pengurusan dewan membenarkannya. Dekorasi yang sesuai akan menyerlahkan suasana majlis dan memberikan pengalaman visual yang menakjubkan buat tetamu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"7. Perkhidmatan Katering dan Menu","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396710826-IN-SewaDewanKahwin-Katering/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Makanan adalah antara perkara yang paling diingati oleh tetamu. Oleh itu, pastikan anda memilih perkhidmatan katering yang berkualiti. Sesetengah dewan menyediakan katering sendiri, manakala ada juga yang membenarkan vendor luar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pastikan menu yang disediakan sesuai dengan cita rasa tetamu dari pelbagai peringkat umur. Elakkan makanan terlalu pedas atau terlalu berat. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Jika boleh, lakukan ","type":"text"},{"text":"food tasting sebelum hari majlis","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/15-questions-to-ask-a-wedding-caterer/","class":null,"target":"_blank"}}]},{"text":". Jangan lupa juga untuk berbincang tentang jumlah hidangan tambahan (","type":"text"},{"text":"extra pax","type":"text","marks":[{"type":"italic"}]},{"text":") sekiranya tetamu hadir melebihi jangkaan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"9. Tentukan Tarikh dan Masa yang Sesuai","type":"text"}]},{"type":"paragraph","content":[{"text":"Tarikh dan masa memainkan peranan besar dalam menentukan harga dan ketersediaan dewan. Musim cuti sekolah dan cuti umum biasanya menjadi waktu paling sibuk dan mahal. Jika ingin berjimat, pilih tarikh luar musim atau waktu pagi/malam hari bekerja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selain itu, pastikan anda menempah sekurang-kurangnya 6 bulan lebih awal untuk mengelakkan risiko dewan penuh. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Semak juga jadual aktiviti lain yang mungkin dijalankan di dewan yang sama supaya tidak berlaku gangguan pada hari majlis.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"10. Semak Ulasan Dewan","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396712211-IN-SewaDewanKahwin-SemakUlasan/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Sebelum membuat sebarang bayaran deposit, semak reputasi dewan tersebut. Baca ulasan pelanggan di Google, Facebook atau laman komuniti. Jika boleh, minta cadangan daripada rakan atau saudara yang pernah menggunakan dewan itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dewan yang mempunyai ulasan positif menunjukkan tahap perkhidmatan yang baik dan pengurusan yang berpengalaman. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Anda juga boleh menilai cara pihak pengurusan berkomunikasi sama ada mereka responsif, mesra dan membantu atau sebaliknya. ","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"11. Syarat Sewa Dewan","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap dewan mempunyai terma dan syarat yang berbeza. Baca dengan teliti semua peraturan sebelum menandatangani sebarang perjanjian. Antara perkara penting yang perlu diberi perhatian ialah:","type":"text"},{"type":"hardBreak"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tempoh masa penggunaan dewan (pagi hingga malam)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Caj tambahan jika masa digunakan melebihi had.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Peraturan membawa makanan luar atau vendor sendiri.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Deposit keselamatan dan polisi pemulangan wang.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Langkah ini penting supaya anda tidak terkejut dengan caj tersembunyi selepas majlis berlangsung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"12.  Tempat Letak Kereta","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396713504-IN-SewaDewanKahwin-TempatLetakKereta/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Tempat letak kereta sering menjadi masalah utama ketika majlis besar. Pastikan dewan yang anda pilih mempunyai kawasan parkir yang luas dan mudah diakses. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Jika ruang terhad, pastikan ada pengurusan trafik atau alternatif seperti parkir tambahan berhampiran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kawasan parkir yang selamat dan teratur bukan sahaja memberi keselesaan kepada tetamu, tetapi juga mengelakkan kekecohan semasa majlis berlangsung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"13. Periksa Dewan Sebelum Bayar Deposit","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/sewa-dewan-kahwin/1787396714716-IN-SewaDewanKahwin-PeriksaDewan/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Langkah terakhir sebelum membuat keputusan ialah melakukan lawatan fizikal ke dewan pilihan anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jangan hanya bergantung kepada gambar di media sosial. Lihat sendiri keadaan sebenar pencahayaan, kebersihan, susun atur, dan kemudahan yang tersedia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anda juga boleh hadir semasa ada majlis berlangsung untuk melihat bagaimana pihak dewan menguruskan acara sebenar. Ini akan memberi gambaran yang lebih jelas tentang bagaimana majlis anda nanti dijalankan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kesimpulan","type":"text"}]},{"type":"paragraph","content":[{"text":"Menyewa dewan perkahwinan bukan hanya tentang mencari tempat yang cantik, tetapi memastikan semua aspek penting diambil kira. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Gunakan ","type":"text"},{"text":"checklist sewa dewan kahwin ","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/complete-checklist-for-an-outdoor-wedding-in-the-tropics/","class":null,"target":"_blank"}}]},{"text":"ini untuk membuat keputusan bijak dan elak risiko pada hari majlis.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jangan terburu-buru membayar deposit sebelum yakin pilihan anda sesuai dengan bajet, lokasi dan keperluan majlis.","type":"text"}]},{"type":"paragraph","content":[{"text":"Artikel Lain:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cara Buat Kad Kahwin Digital Sendiri – Lengkap Dengan Contoh & Template Percuma","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/cara-buat-kad-kahwin-digital/","class":null,"target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hantaran Kahwin Lengkap Untuk Lelaki dan Perempuan – Panduan & Tips Bajet Terkini","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/hantaran-kahwin/","class":null,"target":"_blank"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mas Kahwin Ikut Negeri: Negeri Mana Paling Tinggi & Paling Rendah?","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/mas-kahwin-ikut-negeri/","class":null,"target":"_blank"}}]}]}]}]}]}'::jsonb
  where id = '28fbd806-60db-4e53-9ece-294778438e14';

