  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kad kahwin digital semakin popular kerana lebih moden, cepat disiapkan dan menjimatkan kos. Ia boleh direka terus dari telefon, dihantar melalui WhatsApp, serta dilengkapi fungsi interaktif seperti Google Maps dan RSVP.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dalam artikel ini, kami kongsikan ","type":"text"},{"text":"cara membuat kad kahwin digital sendiri","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/ideas-and-advice/wedding-invitation-card-designs-for-every-style/","class":null,"target":"_blank"}}]},{"text":" berserta contoh dan template percuma yang mudah digunakan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa itu Kad Kahwin Digital","type":"text"}]},{"type":"paragraph","content":[{"text":"Kad kahwin digital ialah versi kad jemputan perkahwinan dalam bentuk digital yang dihantar secara online melalui pautan (link), QR code, WhatsApp, media sosial atau e-mel. Ia menggantikan kad fizikal tradisional dan memudahkan tetamu menerima maklumat majlis dengan cepat, jelas dan interaktif.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kad kahwin digital biasanya mengandungi butiran lengkap seperti:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nama pasangan pengantin","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tarikh, masa dan lokasi majlis","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Peta Google Maps","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"QR code untuk RSVP atau pengesahan kehadiran","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gambar atau video pasangan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Butang RSVP, pautan ke media sosial, playlist lagu, dan sebagainya","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Kad digital juga boleh datang dalam bentuk poster digital, mini website (microsite), video jemputan, atau e-card animasi.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Beza Kad Kahwin Biasa vs Kad Kahwin Digital","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perkara","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Kahwin Biasa","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kad Kahwin Digital","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bentuk","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dicetak pada kertas / kad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dalam bentuk link, gambar, poster, video atau microsite","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Cara Penghantaran","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Diberi secara tangan atau pos","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Dihantar melalui WhatsApp, media sosial atau e-mel","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kos","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kos cetakan dan tempahan lebih tinggi","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Lebih murah, tiada kos cetakan","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kemudahan Tetamu","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perlu simpan kad untuk rujukan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mudah diakses bila-bila masa melalui telefon","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Maklumat Tambahan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terhad pada ruang kad","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Boleh letak Google Maps, RSVP, galeri gambar, muzik, video","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kemas Kini Maklumat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sukar jika berlaku perubahan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Boleh dikemaskini bila-bila masa","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Mesra Alam","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Menggunakan kertas","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada penggunaan kertas, mesra alam","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kuantiti","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perlu cetak mengikut bilangan tetamu","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada had kuantiti","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Rekaan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terhad kepada cetakan dua muka","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Rekaan interaktif, animasi, video dan elemen bergerak","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ketahanan","type":"text"}]}]},{"type":"tabl