  cover_image_url = 'https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/low.webp","sizeBytes":46106},"high":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/high.webp","sizeBytes":265426},"original":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz.jpg","sizeBytes":1180825}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/crop-16x9-og.webp?v=0.8099_0.9334-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/crop-4x3-article-card.webp?v=0.8099_0.9334-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/crop-4x5-mobile-cover.webp?v=0.8099_0.9334-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/apa-itu-mas-kahwin/1787655885049-images-s-pengantin-putih-jambangan-azman-aziz/crop-4.3x1-desktop-hero.webp?v=0.8099_0.9334-g48c0b959","width":2464,"height":700}}'::jsonb,
