  cover_image_url = 'https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/low.webp","sizeBytes":61244},"high":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/high.webp","sizeBytes":386306},"original":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz.jpg","sizeBytes":2297572}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/crop-16x9-og.webp?v=0.0833_0.1560-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/crop-4x3-article-card.webp?v=0.0833_0.1560-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/crop-4x5-mobile-cover.webp?v=0.0833_0.1560-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/taaruf-maksud/1787654732894-images-s-pasangan-baju-oren-azman-aziz/crop-4.3x1-desktop-hero.webp?v=0.0833_0.1560-g48c0b959","width":2463,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.083343505859375,"y":0.15598095935554743,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Taaruf maksudnya proses berkenalan antara lelaki dan perempuan dengan niat untuk berkahwin, dilakukan mengikut batas syarak. Takrif itu datang daripada Jabatan Mufti Wilayah Persekutuan dalam Irsyad Hukum Siri ke-854 bertarikh 26 Jun 2024. Bezanya dengan bercinta bukan pada perasaan, tetapi pada tiga perkara: niatnya dinyatakan awal, ada orang ketiga yang hadir, dan ia tidak dibiarkan berpanjangan tanpa keputusan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perkataan taaruf berasal daripada kata akar Arab yang bermaksud berkenal-kenalan, akar yang sama dengan perkataan ","type":"text"},{"text":"lita''arafu","type":"text","marks":[{"type":"italic"}]},{"text":" dalam surah al-Hujurat ayat 13.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Beza taaruf dengan bercinta","type":"text"}]},{"type":"paragraph","content":[{"text":"Ini bukan dua nama bagi benda yang sama.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Taaruf","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bercinta","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Niat dinyatakan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Di awal, dan ia syarat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Selalunya tidak, atau jauh kemudian","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Siapa hadir","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Wali, mahram atau perantara yang dipercayai","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Berdua","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tempoh","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Menuju satu keputusan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terbuka","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Yang dibincangkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perkara yang menentukan kesesuaian berumah tangga","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terpulang","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sentuhan fizikal","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tidak dibenarkan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Bergantung pada pasangan","type":"text"}]}]}]}]},{"type":"paragraph","content":[{"text":"Baris \"siapa hadir\" itulah yang paling kerap dilanggar, dan ia juga baris yang paling jelas hukumnya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lapan garis panduan taaruf","type":"text"}]},{"type":"paragraph","content":[{"text":"Irsyad Hukum Siri ke-854 diterbitkan menjawab satu soalan praktikal: bolehkah orang bujang bertemu di tempat terbuka seperti restoran untuk berkenalan, seperti ","type":"text"},{"text":"speed dating","type":"text","marks":[{"type":"italic"}]},{"text":"? Jabatan Mufti Wilayah Persekutuan menjawabnya dengan lapan garis panduan.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bertemu bersama wali atau mahram.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menggunakan orang perantaraan yang dipercayai dan bertindak dalam batas syarak.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menyatakan niat untuk berkahwin dengan jelas.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tidak berterusan berkenalan dalam keadaan berdua-duaan tanpa mahram dan tanpa keperluan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menutup aurat dengan sempurna.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menjaga adab dan menundukkan pandangan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Perempuan tidak melembutkan suara atau melakukan gerak-geri yang menggoda.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mengelak sentuhan fizikal antara lelaki dan perempuan.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Antara dalil yang dibawa dalam jawapan itu ialah riwayat Abdullah Ibn Abbas dalam Sahih Muslim, iaitu seorang lelaki tidak boleh bersendirian dengan seorang perempuan melainkan ada mahram bersamanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesimpulan jabatan itu ditulis begini: \"Dalam usaha mencari pasangan, seorang muslim hendaklah meletakkan Allah sebagai pelindung agar tidak terdedah dengan keseronokan dalam bersosial ketika taaruf. Hal ini kerana perkahwinan yang diberkati bermula sebelum akad itu sendiri iaitu dari kesungguhan seseorang menjaga dirinya daripada segala perbuatan yang dilarang oleh syarak.\"","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang boleh dilihat dan ditanya","type":"text"}]},{"type":"paragraph","content":[{"text":"Taaruf bukan temu duga buta. Irsyad Hukum Siri ke-854 membawa riwayat Abu Daud bahawa apabila seseorang meminang, jika dia mampu melihat perempuan itu bagi sesuatu yang menggalakkannya berkahwin, maka lakukanlah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jawapan yang sama juga membawa dua hadis yang lazim disebut tentang pemilihan pasangan: riwayat al-Bukhari bahawa perempuan dikahwini kerana empat perkara iaitu harta, keturunan, kecantikan dan agama, dan pilihlah yang beragama; dan riwayat Ibn Majah bahawa apabila datang seseorang yang kamu redhai akhlak dan agamanya, maka kahwinkanlah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perhatikan bahawa kedua-dua hadis itu bercakap tentang akhlak dan agama sebagai penentu, bukan tentang gaji, kelulusan atau keturunan. Itu perkara yang mudah disebut dan susah diikut, dan ia layak dibincangkan sebelum pertunangan, bukan selepasnya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Khalwat bukan sekadar dosa. Ia kesalahan undang-undang","type":"text"}]},{"type":"paragraph","content":[{"text":"Artikel tentang taaruf jarang menyebut bahagian ini, dan ia bahagian yang boleh menyebabkan seseorang didakwa di Mahkamah Syariah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 29 Enakmen Jenayah Syariah (Selangor) 1995, bertajuk Khalwat, berbunyi:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Mana-mana (a) orang lelaki yang didapati berada bersama dengan seorang atau lebih daripada seorang perempuan yang bukan isteri atau mahramnya; (b) orang perempuan yang didapati berada bersama dengan seorang atau lebih daripada seorang lelaki yang bukan suami atau mahramnya, di mana-mana tempat yang terselindung atau di dalam rumah atau bilik dalam keadaan yang boleh menimbulkan syak bahawa mereka sedang melakukan perbuatan yang tidak bermoral adalah melakukan suatu kesalahan dan apabila disabitkan boleh didenda tidak melebihi tiga ribu ringgit atau dipenjarakan selama tempoh tidak melebihi dua tahun atau kedua-duanya.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Dua perkara berbaloi diperhatikan dalam teks itu. Pertama, kesalahan itu tidak memerlukan bukti apa-apa perbuatan berlaku; yang perlu ialah keadaan yang boleh menimbulkan syak. Kedua, hukumannya sebenar: sehingga RM3,000, atau penjara sehingga dua tahun, atau kedua-duanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang dipetik di atas ialah Selangor. Setiap negeri mempunyai enakmen jenayah syariahnya sendiri, dan nombor seksyen serta kadar hukumannya tidak semestinya sama. Semak enakmen negeri anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bertunang tidak mengubah kedudukan ini. Pertunangan bukan akad, dan pasangan yang bertunang masih ajnabi antara satu sama lain.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Doa jodoh yang ada sandarannya","type":"text"}]},{"type":"paragraph","content":[{"text":"Banyak doa beredar di bawah tajuk \"doa jodoh\". Yang berikut ini dipetik oleh Jabatan Mufti Wilayah Persekutuan sendiri dalam Irsyad Hukum Siri ke-577 bertarikh 12 Jun 2021, jawapan kepada soalan seorang perempuan berusia 33 tahun tentang jodoh yang lambat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semua tiga adalah ayat al-Quran. Terjemahan di bawah ialah terjemahan Abdullah Muhammad Basmeih, iaitu terjemahan rasmi Tafsir Pimpinan Ar-Rahman. Rumi diberikan sebagai panduan sebutan sahaja; teks Arab itulah yang menjadi rujukan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Surah Ali Imran, ayat 38","type":"text","marks":[{"type":"bold"}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Rabbi hab li min ladunka zurriyyatan tayyibah, innaka sami''ud du''a.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"\"Wahai Tuhanku! Kurniakanlah kepadaku dari sisiMu zuriat keturunan yang baik; sesungguhnya Engkau sentiasa Mendengar (menerima) doa permohonan.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Surah al-Anbiya'', ayat 89","type":"text","marks":[{"type":"bold"}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Rabbi la tazarni fardan wa anta khairul warithin.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"\"Wahai Tuhanku! Janganlah Engkau biarkan daku seorang diri (dengan tidak meninggalkan zuriat); dan Engkaulah jua sebaik-baik yang mewarisi.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Surah al-Furqan, ayat 74","type":"text","marks":[{"type":"bold"}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Rabbana hab lana min azwajina wa zurriyyatina qurrata a''yun, waj''alna lil-muttaqina imama.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"\"Wahai Tuhan kami, berilah kami beroleh dari isteri-isteri dan zuriat keturunan kami: perkara-perkara yang menyukakan hati melihatnya, dan jadikanlah kami imam ikutan bagi orang-orang yang (mahu) bertaqwa.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu nota yang jujur tentang dua ayat pertama. Kedua-duanya doa Nabi Zakaria memohon zuriat, bukan doa yang diturunkan khusus untuk memohon pasangan. Jabatan Mufti Wilayah Persekutuan memetiknya dalam konteks jodoh, dan itulah cara ia dilaporkan di sini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesimpulan Irsyad Hukum Siri ke-577: \"jodoh adalah urusan takdir yang telah ditentukan oleh Allah SWT. Ia tidak berkait dengan perwatakan seseorang individu. Namun, seorang hamba perlu berusaha dan berikhtiar serta tidak lekang untuk terus berdoa agar dikurniakan jodoh yang baik.\"","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bolehkah sebut nama seseorang dalam doa jodoh","type":"text"}]},{"type":"paragraph","content":[{"text":"Soalan ini paling kerap ditanya dalam bab ini, dan paling kerap dijawab dengan tekaan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Negeri Selangor menjawabnya melalui sistem e-Musykil pada 2023. Soalannya: wajarkah kita mendoakan seseorang secara spesifik untuk menjadi suami atau isteri kita?","type":"text"}]},{"type":"paragraph","content":[{"text":"Jawapan jabatan itu: boleh. Ia bersandarkan surah Ghafir ayat 60, iaitu Allah menyeru hamba-Nya berdoa dan Dia akan memperkenankan. Jabatan itu menambah bahawa tidak semua doa dimakbulkan dalam bentuk yang diminta; kadangkala ia disimpan sebagai ganjaran di akhirat, atau dijadikan pelindung daripada sesuatu keburukan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang disyorkan dalam jawapan yang sama ialah kaedah istikharah, iaitu memohon supaya jika orang itu baik bagi agama, iman dan kehidupan kita, maka Allah permudahkan, dan jika tidak, maka Allah jauhkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi bukan larangan, tetapi cara memintanya penting: memohon supaya dipermudahkan jika ia baik, bukan memohon supaya jadi tanpa syarat.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Istikharah untuk jodoh, dan apa maksud \"tanda\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Solat istikharah ialah solat sunat dua rakaat untuk memohon pilihan terbaik daripada Allah. Al-Kafi #829 bertarikh 4 Oktober 2018 daripada Jabatan Mufti Wilayah Persekutuan menerangkannya, bersandarkan hadis Jabir bin Abdullah yang diriwayatkan al-Tirmizi (480) dan Ibnu Majah (1383). Imam al-Tirmizi menilai hadis itu hasan sahih gharib.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hukumnya sunat. Jabatan itu menyatakan sesiapa yang ada hajat atau ingin memohon petunjuk tentang sesuatu perkara disunatkan solat dua rakaat dan berdoa dengan doa yang diajarkan Nabi SAW dalam hadis Jabir itu.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kaifiat, mengikut Imam al-Nawawi","type":"text"}]},{"type":"paragraph","content":[{"text":"Al-Kafi #829 memetik al-Majmu'' Syarh al-Muhazzab (4/54):","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rakaat pertama, selepas al-Fatihah, harus membaca surah al-Kafirun.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rakaat kedua, selepas al-Fatihah, harus membaca surah al-Ikhlas.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berdoa dengan doa yang diajarkan Nabi SAW, ataupun doa-doa yang sesuai.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Al-Kafi #1803 bertarikh 20 Jun 2021 menambah bahawa dua rakaat itulah yang afdal dan disepakati empat mazhab, dan lebih daripada dua rakaat diharuskan dalam mazhab Syafie.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Doa istikharah","type":"text"}]},{"type":"paragraph","content":[{"text":"Teks Arab di bawah disalin daripada hadis Jabir bin Abdullah seperti diterbitkan dalam Al-Kafi #829, dan terjemahannya ialah terjemahan jabatan itu sendiri. Rumi diberikan sebagai panduan sebutan sahaja.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ ، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ ، وَتَعْلَمُ وَلاَ أَعْلَمُ ، وَأَنْتَ عَلاَّمُ الغُيُوبِ ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعِيشَتِي وَعَاقِبَةِ أَمْرِي ، فَيَسِّرْهُ لِي ، ثُمَّ بَارِكْ لِي فِيهِ ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعِيشَتِي وَعَاقِبَةِ أَمْرِي ، فَاصْرِفْهُ عَنِّي ، وَاصْرِفْنِي عَنْهُ ، وَاقْدُرْ لِي الخَيْرَ حَيْثُ كَانَ ، ثُمَّ أَرْضِنِي بِهِ","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Allahumma inni astakhiruka bi''ilmika, wa astaqdiruka biqudratika, wa as''aluka min fadlikal ''azim. Fa innaka taqdiru wa la aqdir, wa ta''lamu wa la a''lam, wa anta ''allamul ghuyub. Allahumma in kunta ta''lamu anna hazal amra khairun li fi dini wa ma''isyati wa ''aqibati amri, fayassirhu li, thumma barik li fih. Wa in kunta ta''lamu anna hazal amra syarrun li fi dini wa ma''isyati wa ''aqibati amri, fasrifhu ''anni, wasrifni ''anhu, waqdur liyal khaira haithu kana, thumma ardini bih.","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Terjemahan Jabatan Mufti Wilayah Persekutuan: \"Ya Allah, aku memohon pilihan dengan ilmu-Mu, aku memohon kekuatan dengan kekuatan-Mu, Aku juga memohon daripada limpahan-Mu yang Agung. Engkau mampu sedangkan aku tidak. Engkau Maha Mengetahui sedangkan aku tidak tahu. Engkau Maha Tahu tentang perkara yang ghaib. Ya Allah, jika Engkau mengetahui bahawa perkara ini baik untuk agamaku, kehidupanku dan penghujungku, maka permudahkanlah urusanku dan berkatilah aku dalam urusan tersebut. Jika Engkau tahu bahawa perkara ini buruk bagiku pada agamaku, kehidupanku dan penghujung hidupku, maka jauhkanlah ia dariku dan jauhkan aku darinya. Dan tentukan bagiku yang terbaik kemudian redhailah aku dengannya.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Dua nota tentang teks itu, supaya tiada yang tersalah anggap:","type":"text"}]},{"type":"paragraph","content":[{"text":"Riwayat itu merekodkan satu lagi lafaz yang dilaporkan Jabir sebagai ganti kepada \"","type":"text"},{"text":"wa ''aqibati amri","type":"text","marks":[{"type":"italic"}]},{"text":"\" (penghujung urusanku), iaitu \"","type":"text"},{"text":"fi ''ajili amri wa ajilih","type":"text","marks":[{"type":"italic"}]},{"text":"\" (yang segera dan yang lambat). Kedua-duanya datang dalam riwayat yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dan inilah yang menjadikannya istikharah ","type":"text"},{"text":"jodoh","type":"text","marks":[{"type":"bold"}]},{"text":". Hujung hadis itu berbunyi \"وَيُسَمِّي حَاجَتَهُ\", diterjemahkan oleh jabatan itu sebagai: \"Orang itu (boleh) menyatakan hajatnya.\" Jadi tiada doa istikharah khusus untuk jodoh yang berasingan. Yang ada ialah satu doa, dan anda menyebut hajat anda di dalamnya.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Tandanya bukan mimpi","type":"text"}]},{"type":"paragraph","content":[{"text":"Mimpi bukan syarat, walaupun itulah yang paling ramai percaya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Irsyad al-Fatwa Siri ke-342 bertarikh 11 Disember 2019 menjawab soalan itu terus. Jawapannya: bermimpi \"tiada sandaran di dalam syarak dan tidak disyaratkan jawapan tersebut melalui mimpi sahaja\". Kesimpulan jabatan itu: \"tidak disyaratkan untuk bermimpi untuk mendapat jawapan terhadap istikharah yang dilakukan, bahkan tidak memerlukan apa-apa petunjuk melainkan dengan dilapangkan dadanya dan dipermudahkan urusan.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Tandanya, mengikut Imam al-Nawawi seperti dipetik dalam jawapan itu, ialah apa yang dilapangkan dadanya dalam membuat keputusan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu lagi amalan yang perlu disebut: membuka al-Quran secara rawak dan membaca terjemahan ayat yang terbuka sebagai jawapan istikharah. Irsyad Hukum Siri ke-586 bertarikh 30 Jun 2021 menyatakan tiada dalil khusus dan sahih baginya, ulama berbeza pandangan antara haram, makruh dan harus, dan pendapat muktamad dalam mazhab Syafie ialah makruh.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang disyorkan sebaliknya ialah kaedah yang diajar Nabi SAW: solat dua rakaat, doa, dan berbincang dengan orang yang berpengalaman.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau tiada keluarga atau ustaz yang boleh mengaturkan","type":"text"}]},{"type":"paragraph","content":[{"text":"Keadaan ini benar-benar berlaku, dan ia patut dijawab dengan jujur.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kami tidak menemui sebarang program taaruf rasmi yang dikendalikan JAKIM atau jabatan agama Islam negeri untuk mempertemukan pasangan. Yang wujud di pasaran ialah aplikasi dan portal swasta, dan kami tidak mengesyorkan mana-mana satu kerana tiada satu pun yang disahkan oleh mana-mana pihak berkuasa agama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang boleh dipegang ialah garis panduan itu sendiri. Garis panduan kedua dalam Irsyad Hukum Siri ke-854 menyebut orang perantaraan yang dipercayai dan bertindak dalam batas syarak. Perantara itu tidak semestinya ibu bapa. Ia boleh imam masjid kariah, guru, atau pasangan berkahwin yang mengenali kedua-dua belah pihak dan sanggup hadir dalam pertemuan itu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang tidak boleh diubah ialah syaratnya: ada orang ketiga, niat dinyatakan, dan tiada pertemuan berdua-duaan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang taaruf tidak jamin","type":"text"}]},{"type":"paragraph","content":[{"text":"Taaruf ialah kaedah, bukan jaminan. Ia tidak menjamin perkahwinan yang baik, dan ia tidak menjamin anda tidak akan silap menilai orang.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang ia lakukan ialah menjaga dua perkara sekali gus: batas syarak sepanjang tempoh berkenalan, dan kejujuran maklumat, kerana kehadiran orang ketiga menyukarkan kedua-dua belah pihak melebih-lebihkan diri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selepas taaruf datang merisik, meminang dan pertunangan, dan selepas itu barulah soal hantaran dan mas kahwin. Bahagian yang melibatkan wang dan barang itu bermula dengan satu takrif yang ramai keliru, dan ia diterangkan dalam ","type":"text"},{"text":"maksud mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin/apa-itu-mas-kahwin","class":null,"target":"_blank"}}]},{"text":" serta ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sumber","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad Hukum Siri Ke-854: Garis Panduan Taaruf Menurut Islam, 26 Jun 2024. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad Hukum Siri Ke-577: Jodoh Tak Lekat; Silap Siapa?, 12 Jun 2021. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Al-Kafi #829: Apa Itu Istikharah?, 4 Oktober 2018. Sumber teks Arab dan terjemahan doa istikharah, hadis Jabir bin Abdullah riwayat al-Tirmizi (480) dan Ibnu Majah (1383), serta kaifiat Imam al-Nawawi dalam al-Majmu'' Syarh al-Muhazzab (4/54). Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Al-Kafi #1803: Hukum Melakukan Solat Sunat Istikharah Lebih Daripada Dua Rakaat, 20 Jun 2021. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad al-Fatwa Siri Ke-342: Adakah Disyaratkan Bermimpi Sebagai Jawapan Istikharah?, 11 Disember 2019. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad Hukum Siri Ke-586: Hukum Melakukan Istikharah Dengan Membuka Al-Quran Secara Rawak, 30 Jun 2021. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Negeri Selangor, Sistem e-Musykil, jawapan 3567, kategori Munakahat, 2023. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Jenayah Syariah (Selangor) 1995, seksyen 29, teks daripada portal enakmen Dewan Negeri Selangor. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Teks al-Quran dan terjemahan Abdullah Muhammad Basmeih (Tafsir Pimpinan Ar-Rahman) bagi Ali Imran 38, al-Anbiya'' 89, al-Furqan 74 dan al-Hujurat 13. Disemak 25 Ogos 2026.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hukum yang dilaporkan di sini datang daripada Jabatan Mufti Wilayah Persekutuan dan Jabatan Mufti Negeri Selangor, dan dilaporkan sebagaimana mereka menerbitkannya. Enakmen jenayah syariah berbeza mengikut negeri. Untuk keadaan anda sendiri, rujuk jabatan mufti atau pejabat agama Islam negeri anda.","type":"text"}]}]}'::jsonb
  where id = '4916bdcf-c183-473a-b96a-115d3d7d0350';

-- doa-majlis-pertunangan  (updated_at was 2026-08-25T10:45:52.566Z)
update articles set
  cover_image_url = 'https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim.jpg',
  cover_image_variants = '{"low":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/low.webp","sizeBytes":22886},"high":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/high.webp","sizeBytes":127782},"original":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim.jpg","sizeBytes":7335703}}'::jsonb,
  cover_image_smart_crops = '{"crop-16x9-og":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/crop-16x9-og.webp?v=0.7801_0.6539-g48c0b959","width":1200,"height":630},"crop-4x3-article-card":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/crop-4x3-article-card.webp?v=0.7801_0.6539-g48c0b959","width":1600,"height":1200},"crop-4x5-mobile-cover":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/crop-4x5-mobile-cover.webp?v=0.7801_0.6539-g48c0b959","width":1920,"height":2400},"crop-4.3x1-desktop-hero":{"url":"https://images.hellokahwin.com/inspire/doa-majlis-pertunangan/1787654741688-images-s-lelaki-menadah-doa-ahmad-ali-karim/crop-4.3x1-desktop-hero.webp?v=0.7801_0.6539-g48c0b959","width":2464,"height":700}}'::jsonb,
  cover_image_focal_point = '{"x":0.78009521484375,"y":0.653920175759795,"method":"saliency"}'::jsonb,
  cover_image_detection_data = '{"faces":{"disabled":"rekognition"},"labels":{"disabled":"rekognition"}}'::jsonb,
  content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tiada doa khusus untuk majlis pertunangan yang diterbitkan oleh JAKIM, oleh mana-mana jabatan mufti, atau oleh mana-mana jabatan agama Islam negeri. Kami menyemaknya dan tidak menemuinya. Doa yang beredar di bawah tajuk itu datang daripada laman web dan dokumen kongsian, bukan daripada pihak berkuasa. Yang ada dan boleh dipegang ialah garis panduan rasmi tentang cara sesebuah doa majlis disusun, dan itu boleh dipakai pada majlis pertunangan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kenapa tiada doa khusus untuk pertunangan","type":"text"}]},{"type":"paragraph","content":[{"text":"Pertunangan bukan satu ibadat khusus dan bukan satu akad. Ia janji untuk berkahwin. Tiada lafaz yang perlu betul, tiada rukun yang boleh batal, dan kerana itu tiada doa yang ditetapkan untuknya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi majlis pertunangan yang tidak dibacakan doa tetap sah sepenuhnya, kerana tiada apa-apa untuk disahkan. Doa dibaca kerana ia baik, bukan kerana ia dituntut.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa yang JAKIM benar-benar terbitkan","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Kemajuan Islam Malaysia menerbitkan ","type":"text"},{"text":"Garis Panduan dan Himpunan Doa Bagi Majlis Rasmi dan Separuh Rasmi Kerajaan","type":"text","marks":[{"type":"italic"}]},{"text":", terbitan 2026. Namanya menyatakan skopnya: ia untuk majlis kerajaan, dan majlis pertunangan bukan salah satu daripadanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kami tetap membawanya di sini kerana ia satu-satunya piawai bertulis tentang doa majlis yang diterbitkan pihak berkuasa agama di Malaysia. Ia garis panduan kerajaan yang boleh diikut, bukan hukum yang mengikat majlis keluarga anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semak edisi sebelum anda memetik apa-apa angka daripadanya. Tiga versi dokumen ini masih boleh dimuat turun dari islam.gov.my hari ini, dan ia tidak sama. Yang paling kerap muncul dalam carian ialah yang paling lama.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph"}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Edisi lama, tanpa tarikh","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terbitan 2025","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terbitan 2026 (semasa)","type":"text","marks":[{"type":"bold"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tajuk","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Garis Panduan Tatacara Membaca Doa Di Majlis-Majlis Rasmi Dan Separuh Rasmi Kerajaan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Garis Panduan dan Himpunan Doa Bagi Majlis Rasmi dan Separuh Rasmi Kerajaan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sama seperti 2025","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Muka surat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"76","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"60","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"28","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tempoh doa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tidak melebihi 5 minit","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Antara 2 hingga 3 minit","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Antara 2 hingga 3 minit","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pembaca doa","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"\"Seelok-eloknya seorang lelaki\"","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"\"Hendaklah seorang lelaki\"","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"\"Hendaklah seorang lelaki\"","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Doa perkahwinan dalam koleksi","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ada","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Ada","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","content":[{"text":"Nombor perenggan tidak sepadan antara edisi. Semua rujukan perenggan di bawah ialah nombor edisi 2026.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Rangka doa, mengikut edisi 2026","type":"text"}]},{"type":"paragraph","content":[{"text":"Perenggan 6 menetapkan susunan teks doa:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mukadimah (6.1) hendaklah mengandungi lafaz puji-pujian kepada Allah SWT dan selawat ke atas Nabi Muhammad SAW dalam Bahasa Arab, dan boleh diikuti doa dalam bahasa lain.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Isi kandungan (6.2 i) hendaklah mengandungi permohonan untuk keselamatan dan kesejahteraan umum, diikuti permohonan khusus yang sesuai dengan majlis berkenaan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Setiap perenggan (6.2 ii) sebaik-baiknya menyebut nama dan sifat Allah SWT yang sesuai dengan perkara yang dipohon.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penutup (6.3) lazimnya doa permohonan keselamatan dunia dan akhirat, dan bahagian akhir hendaklah mengandungi selawat dan tahmid dalam Bahasa Arab.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Satu perkara di sini berubah antara edisi lama dan edisi 2026, dan ia mengubah nasihat yang lazim diberi. Perenggan 6.2 (vi) edisi 2026 berbunyi: \"Isi kandungan doa hendaklah dibaca dalam Bahasa Arab. Terjemahan teks doa dalam Bahasa Melayu, Bahasa Inggeris dan bahasa-bahasa lain boleh disediakan dan dipaparkan di skrin.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi kedudukan semasa bukan \"doa Melayu dibenarkan\". Ia: isi kandungan dibaca dalam Arab, dan ","type":"text"},{"text":"terjemahan Melayu dipaparkan","type":"text","marks":[{"type":"bold"}]},{"text":", bukan dibaca ganti. Perenggan 6.4 menambah bahawa penganjur disyorkan memaparkan teks doa dan terjemahannya di skrin.","type":"text"}]},{"type":"paragraph","content":[{"text":"Perenggan 9 mengurus masanya. Doa sebaik-baiknya dibaca pada permulaan majlis (9.1), dan tempohnya ","type":"text"},{"text":"antara 2 hingga 3 minit","type":"text","marks":[{"type":"bold"}]},{"text":" (9.2). Angka lima minit yang beredar luas datang daripada edisi lama dan bukan kedudukan semasa.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Siapa yang membaca","type":"text"}]},{"type":"paragraph","content":[{"text":"Perenggan 7.2 menetapkan empat kriteria, dan bahasanya lebih tegas daripada edisi lama:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pembaca doa ","type":"text"},{"text":"hendaklah","type":"text","marks":[{"type":"bold"}]},{"text":" seorang lelaki dan beragama Islam, boleh menyebut perkataan dalam bahasanya dengan tepat, fasih dan betul.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dia hendaklah individu yang mempunyai akhlak dan sahsiah baik yang tidak dipertikai oleh pendengar dan masyarakat.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dia mestilah mengetahui kesesuaian doa yang dibaca bagi majlis berkenaan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bagi majlis yang hanya dihadiri golongan wanita, pembaca doa boleh dilantik dalam kalangan wanita.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Perenggan 8 menyenaraikan tatacaranya, dan satu daripadanya berguna kepada keluarga. Perenggan 8.1 menghendaki pembaca doa berhubung dengan penganjur lebih awal untuk mendapatkan tarikh, masa dan tempat majlis, tujuan majlis, nama majlis dan nama orang yang diraikan, serta tentatif program. Perenggan 8.3 pula: beri tanda hormat kepada tetamu, beri salam, dan bacaan surah al-Fatihah sebelum doa mengikut kesesuaian majlis.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pada majlis pertunangan di rumah, semua ini panduan dan bukan syarat. Keluarga biasanya meminta bapa, bapa saudara, imam kariah atau jurucakap pihak lelaki. Yang paling berbaloi diambil ialah perenggan 8.1: beri dia nama, tujuan dan aturcara lebih awal, kerana doa yang tersasar biasanya tersasar sebab pembacanya tidak diberitahu apa-apa sebelum dijemput ke hadapan.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Majlis yang garis panduan itu larang doa dibaca","type":"text"}]},{"type":"paragraph","content":[{"text":"Perenggan 5.3 menyenaraikan majlis yang tidak sepatutnya dibacakan doa. Antaranya majlis yang berunsur maksiat seperti hidangan arak atau perjudian, dan majlis yang bercampur dengan \"acara nyanyian, karaoke, tari-menari, berlakunya pergaulan bebas antara lelaki dan perempuan dan sebagainya.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Sekali lagi, skop dokumen itu majlis kerajaan. Ia bukan hukum ke atas majlis keluarga anda, dan kami tidak mengeluarkan apa-apa hukum tentang majlis anda di sini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia dibawa kerana satu sebab praktikal: inilah dokumen yang dirujuk oleh sebahagian pegawai agama. Kalau seseorang yang anda jemput teragak-agak atau menolak, senarai itu selalunya puncanya, dan lebih mudah dibincangkan awal daripada pada malam majlis.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Tiada contoh doa pertunangan dalam mana-mana edisi","type":"text"}]},{"type":"paragraph","content":[{"text":"Koleksi teks doa dalam edisi 2026 mengandungi empat doa sahaja: doa lawatan kerja rasmi Seri Paduka Baginda Yang di-Pertuan Agong, doa majlis pembukaan rasmi Sidang Parlimen, doa perjumpaan bulanan Perdana Menteri bersama warga Jabatan Perdana Menteri, dan doa selamat.","type":"text"}]},{"type":"paragraph","content":[{"text":"Edisi 2025 membawa koleksi yang jauh lebih besar, termasuk Doa Majlis Khenduri Perkahwinan. Edisi 2026 menggugurkannya bersama kebanyakan yang lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi kedudukannya begini, dan ia sama merentas ketiga-tiga edisi: ada contoh doa untuk pelbagai majlis, dan tiada satu pun untuk pertunangan. Dalam edisi semasa, contoh doa perkahwinan pun sudah tiada.","type":"text"}]},{"type":"paragraph","content":[{"text":"Contoh perkahwinan dalam edisi 2025 itu pun tidak boleh diambil bulat-bulat untuk majlis tunang. Ia menyebut \"kedua mempelai\" dan memohon zuriat, dua perkara yang tidak terpakai kepada pasangan yang baru bertunang. Yang boleh diambil ialah susunannya, bukan ayatnya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Adab berdoa, dan satu contoh yang Mufti Wilayah Persekutuan nasihatkan supaya dielak","type":"text"}]},{"type":"paragraph","content":[{"text":"Sesiapa yang menulis teks doa untuk majlis tunang berdepan dua godaan: memanjangkannya, dan mencantikkannya. Ada jawapan hukum yang baharu tentang kedua-duanya.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pada 16 April 2026, Jabatan Mufti Wilayah Persekutuan menerbitkan Irsyad al-Hukum Siri ke-954 menjawab soalan tentang satu doa yang lazim dibaca di majlis perkahwinan Melayu, iaitu doa yang memohon supaya ikatan pengantin dikukuhkan \"seperti Yusuf dan Zulaikha, Musa dan Safurah, Sulaiman dan Balqis\". Penanya menyebut ada dakwaan kesahihannya tidak dapat dipastikan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jawapan jabatan itu tidak mengharamkannya, tetapi nasihatnya jelas. Kesimpulannya ditulis dalam dua perkara:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"i. Cara berdoa yang baik adalah dengan menjaga adab-adab ketika berdoa. Antara adab tersebut ialah tidak terlalu panjang dan berbunga-bunga sehingga seolah-olah bersajak kerana ia akan menghilangkan rasa khusyuk, perasaan tunduk dan ikhlas kepada Allah SWT.","type":"text"}]},{"type":"paragraph","content":[{"text":"ii. Selain itu juga, jika ingin menambah perkataan yang disebutkan dalam soalan di atas, maka sebaiknya memilih apa yang dipastikan dengan yakin kesahihannya.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Larangan terhadap doa yang bersajak itu bersandarkan riwayat Abu Hurairah dalam Sahih al-Bukhari (6337).","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk sesiapa yang menulis teks doa malam sebelum majlis, nasihatnya praktikal: pendek, jelas, dan tidak dibuat berirama. Doa yang cuba sedap didengar biasanya berhenti menjadi doa.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Doa pengantin yang selalu tersalah tempat","type":"text"}]},{"type":"paragraph","content":[{"text":"Ada satu doa sunnah yang masyhur untuk pasangan yang baru berkahwin, bermula dengan lafaz ","type":"text"},{"text":"Barakallahu laka","type":"text","marks":[{"type":"italic"}]},{"text":". Irsyad al-Hukum Siri ke-954 menyatakan ia dituntut dan bersandarkan riwayat Abu Hurairah dalam Sunan Abu Daud (2130), dan Imam al-Nawawi meletakkannya ","type":"text"},{"text":"selepas akad nikah","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Kerana itu ia bukan doa majlis pertunangan, dan ia kerap dibaca di tempat yang salah. Pasangan yang bertunang belum berkahwin. Mendoakan mereka supaya \"dihimpunkan berdua\" pada malam tunang menyalahi kedudukan sebenar mereka, dan pada malam itu mereka masih ajnabi antara satu sama lain.","type":"text"}]},{"type":"paragraph","content":[{"text":"Doa itu dan teks penuhnya termasuk dalam himpunan doa perkahwinan, bukan dalam skop halaman ini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk majlis pertunangan, doa yang munasabah ialah doa keselamatan majlis, doa dipermudahkan urusan sehingga ke akad, dan doa kesejahteraan kedua-dua keluarga. Itu semua doa umum, dan doa umum tidak memerlukan nas khusus.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Satu lagi hadis yang beredar, dan statusnya","type":"text"}]},{"type":"paragraph","content":[{"text":"Kalimah \"zahirkan pernikahan dan sembunyikan pertunangan\" kerap dipetik apabila orang bertanya sama ada tunang patut diraikan besar-besaran.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, dalam Irsyad al-Fatwa ke-163 bertarikh 16 Januari 2017, menyemaknya. Riwayat itu daripada Ummu Salamah, dikeluarkan oleh al-Imam al-Dailami dalam ","type":"text"},{"text":"Musnad al-Firdaus","type":"text","marks":[{"type":"italic"}]},{"text":", dan sebahagian ulama menilainya dhaif kerana ada perawi yang tidak dikenali.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jadi kalau ada yang memetiknya kepada anda sebagai dalil, itu bukan hujah yang kukuh. Yang kukuh ialah riwayat Ibn ''Umar dalam Sahih Muslim (1412), iaitu larangan meminang atas pinangan saudaranya. Dan itu sebenarnya hujah ke arah memberitahu orang, bukan menyembunyikan.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jangan sambut tunang seperti majlis kahwin","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesimpulan Irsyad al-Fatwa ke-163 layak dibaca sepenuhnya oleh mana-mana keluarga yang sedang merancang belanja majlis tunang:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Tiada masalah untuk seseorang itu menghebahkan pertunangannya. Namun janganlah berlebih-lebihan dalam menghebahkannya serta menyambutnya seolah-olah seperti berlangsungnya majlis perkahwinan kerana pertunangan itu adalah perjanjian menuju perkahwinan dan boleh sahaja sesuatu pertunangan itu dibatalkan.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Sebabnya bukan soal berjimat. Sebabnya soal apa yang dipertaruhkan. Pertunangan boleh putus, dan apabila ia putus, wang yang sudah dibelanjakan menjadi perkara yang boleh dituntut di Mahkamah Syariah.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kalau pertunangan putus","type":"text"}]},{"type":"paragraph","content":[{"text":"Seksyen 15 Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003, bertajuk Pertunangan, memperuntukkan:","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"Jika seseorang telah mengikat suatu pertunangan mengikut Hukum Syarak, sama ada secara lisan atau secara bertulis, dan sama ada secara bersendirian atau melalui seorang perantaraan, dan kemudiannya enggan berkahwin dengan pihak yang satu lagi itu tanpa apa-apa sebab yang sah manakala pihak yang satu lagi bersetuju berkahwin dengannya, maka pihak yang mungkir adalah bertanggungan memulangkan pemberian-pemberian pertunangan, jika ada, atau nilainya dan membayar apa-apa wang yang telah dibelanjakan dengan suci hati oleh atau untuk pihak yang satu lagi untuk membuat persediaan bagi perkahwinan itu, dan yang demikian boleh dituntut melalui tindakan dalam Mahkamah.\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"Perhatikan bahagian kedua. Bukan setakat pemberian pertunangan: wang yang dibelanjakan untuk persediaan perkahwinan juga boleh dituntut. Semakin besar majlis tunang, semakin besar angka yang tergantung pada janji yang belum menjadi akad.","type":"text"}]},{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, dalam Irsyad al-Fatwa Siri ke-794 bertarikh 29 Ogos 2023, merujuk peruntukan sama di seksyen 15 Akta Undang-Undang Keluarga Islam (Wilayah-Wilayah Persekutuan) 1984, dan menyatakan tuntutan itu dibuat di Mahkamah Syariah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yang dipetik di sini Selangor dan Wilayah Persekutuan. Setiap negeri mempunyai enakmennya sendiri dan nombor seksyen tidak semestinya sama. Semak enakmen negeri anda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Barang dan wang yang bertukar tangan pada peringkat ini, dan bezanya dengan mas kahwin yang wajib pada hari akad, diterangkan dalam ","type":"text"},{"text":"hantaran dan mas kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/artikel/hantaran-mas-kahwin","class":null,"target":"_blank"}}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cara menyusun doa majlis tunang anda","type":"text"}]},{"type":"paragraph","content":[{"text":"Berdasarkan rangka edisi 2026 di atas, dan tanpa mereka-reka apa-apa yang tidak diterbitkan:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mukadimah dalam Arab: puji-pujian kepada Allah SWT dan selawat ke atas Nabi Muhammad SAW.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Permohonan umum: keselamatan dan kesejahteraan tetamu dan kedua-dua keluarga.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Permohonan khusus untuk majlis ini: dipermudahkan urusan kedua-dua keluarga sehingga ke hari akad, dijauhkan perselisihan, dan diberkati apa yang telah dipersetujui.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Penutup dalam Arab: doa keselamatan dunia dan akhirat, kemudian selawat dan tahmid.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Bacakan pada permulaan majlis dan pendekkan kepada dua hingga tiga minit. Beri pembacanya nama dan aturcara lebih awal. Jangan buat berirama. Dan jangan doakan mereka sebagai pasangan yang sudah dihimpunkan, kerana mereka belum.","type":"text"}]},{"type":"paragraph","content":[{"text":"Satu nota tentang bahasa, kerana ia mudah disalah faham. Perenggan 6.2 (vi) di atas mengikat teks doa bagi majlis rasmi dan separuh rasmi kerajaan. Majlis pertunangan di rumah bukan salah satu daripadanya, jadi perenggan itu tidak menetapkan apa-apa untuk majlis anda. Kami tidak mengeluarkan hukum tentang bahasa doa di sini. Kalau itu soalan anda, tanya imam kariah atau pejabat agama Islam daerah anda.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sumber","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Kemajuan Islam Malaysia (JAKIM), ","type":"text"},{"text":"Garis Panduan dan Himpunan Doa Bagi Majlis Rasmi dan Separuh Rasmi Kerajaan","type":"text","marks":[{"type":"italic"}]},{"text":", terbitan 2026, perenggan 6, 7, 8 dan 9, serta senarai kandungan Bahagian 2. Disiarkan di islam.gov.my bertarikh 12 Mac 2026. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Edisi terdahulu yang disemak untuk perbandingan: ","type":"text"},{"text":"Garis Panduan dan Himpunan Doa Bagi Majlis Rasmi dan Separuh Rasmi Kerajaan","type":"text","marks":[{"type":"italic"}]},{"text":", terbitan 2025, 60 muka surat; dan ","type":"text"},{"text":"Garis Panduan Tatacara Membaca Doa Di Majlis-Majlis Rasmi Dan Separuh Rasmi Kerajaan","type":"text","marks":[{"type":"italic"}]},{"text":", edisi tanpa tarikh, 76 muka surat. Kedua-duanya masih boleh dimuat turun di islam.gov.my. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad al-Hukum Siri Ke-954: Persoalan Berkaitan Doa Yang Dibaca Ketika Majlis Perkahwinan, 16 April 2026. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad al-Fatwa Ke-163: Hukum Menyembunyikan Pertunangan, 16 Januari 2017. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jabatan Mufti Wilayah Persekutuan, Irsyad al-Fatwa Siri Ke-794: Hukum Meminta Semula Hadiah Hantaran Apabila Putus Tunang, 29 Ogos 2023. Disemak 25 Ogos 2026.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enakmen Undang-Undang Keluarga Islam (Negeri Selangor) 2003, seksyen 15, teks daripada portal enakmen Dewan Negeri Selangor. Disemak 25 Ogos 2026.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Kami tidak menerbitkan teks penuh sesuatu doa pertunangan kerana tiada pihak berkuasa agama menerbitkannya. Yang dilaporkan di sini ialah garis panduan rasmi dan jawapan hukum yang bertarikh, sebagaimana ia diterbitkan. Untuk majlis anda sendiri, tanya pejabat agama Islam daerah atau imam kariah anda.","type":"text"}]}]}'::jsonb
  where id = '43d1b444-57ee-48e6-9208-293783a498e1';

-- contoh-kad-jemputan-kahwin  (updated_at was 2026-08-25T11:24:56.451Z)
